package com.vandorlabs.neoforge.ramp;

import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.world.phys.*;

/** Typed physical metadata only; asynchronous admission/recovery is tested separately. */
final class NativeRampActorIntentChecks {
 static void run(){var operation=new UUID(1,2);var root=new BlockPos(-20,100,30);String dimension="minecraft:overworld";var row=new NativeRampActorIntent.Participant(new UUID(3,4),"minecraft:pig",new Vec3(-19.5,100,30.5),new Vec3(-19.5,99,30.5),new AABB(-19.95,100,30.05,-19.05,100.9,30.95),new Vec3(.125,0,-.125),3.5F,true,false,true,false);var rows=new ArrayList<NativeRampActorIntent.Participant>();rows.add(row);var intent=new NativeRampActorIntent(operation,dimension,root,rows);rows.clear();need(intent.participants().size()==1,"defensive row list");boolean immutable=false;try{intent.participants().clear();}catch(UnsupportedOperationException expected){immutable=true;}need(immutable,"immutable rows");var tag=intent.write();need(NativeRampActorIntent.read(tag,operation,dimension,root).equals(intent),"exact typed roundtrip");need(!tag.toString().contains("Items")&&!tag.toString().contains("ForgeCaps")&&!tag.toString().contains("Credentials"),"no ownership envelopes");
  for(int variant=0;variant<15;variant++){var broken=tag.copy();var actor=broken.getList("Actors",Tag.TAG_COMPOUND).getCompound(0);switch(variant){case 0->broken.putInt("Schema",2);case 1->broken.putUUID("Operation",new UUID(9,9));case 2->broken.putString("Dimension","minecraft:the_nether");case 3->broken.putIntArray("Root",new int[]{-19,100,30});case 4->broken.putString("Future","unknown");case 5->actor.putString("Items","opaque");case 6->actor.putString("Type","PIG");case 7->actor.putByte("Ground",(byte)2);case 8->actor.putDouble("Fall",3.5);case 9->actor.putFloat("Fall",Float.NaN);case 10->{var list=new ListTag();list.add(DoubleTag.valueOf(0));actor.put("From",list);}case 11->{var list=actor.getList("From",Tag.TAG_DOUBLE);list.set(0,DoubleTag.valueOf(Double.POSITIVE_INFINITY));}case 12->{var list=actor.getList("To",Tag.TAG_DOUBLE);list.set(0,DoubleTag.valueOf(10000));}case 13->{var list=actor.getList("Body",Tag.TAG_DOUBLE);list.set(3,DoubleTag.valueOf(-30));}default->broken.getList("Actors",Tag.TAG_COMPOUND).add(actor.copy());}boolean refused=false;try{NativeRampActorIntent.read(broken,operation,dimension,root);}catch(IllegalArgumentException expected){refused=true;}need(refused,"invalid typed intent variant "+variant);}
  var maximum=new ArrayList<NativeRampActorIntent.Participant>();for(int i=0;i<NativeRampActorIntent.MAX_ACTORS;i++)maximum.add(new NativeRampActorIntent.Participant(new UUID(7,i),row.type(),row.from(),row.to(),row.body(),row.velocity(),row.fall(),row.ground(),row.noPhysics(),row.impulse(),row.hurtMarked()));var bounded=new NativeRampActorIntent(operation,dimension,root,maximum.subList(0,512));need(bounded.retainedBytes()<=NativeRampActorIntent.MAX_BYTES&&NativeRampActorIntent.read(bounded.write(),operation,dimension,root).equals(bounded),"bounded large typed intent");boolean encodedRefused=false;try{new NativeRampActorIntent(operation,dimension,root,maximum).write();}catch(IllegalArgumentException expected){encodedRefused=true;}need(encodedRefused,"encoded budget independently bounds maximum participant count");maximum.add(row);boolean refused=false;try{new NativeRampActorIntent(operation,dimension,root,maximum);}catch(IllegalArgumentException expected){refused=true;}need(refused,"oversized intent refuses before encoding");System.out.println("[vandorlabs][ramp-actor-intent] typed PASS");
 }
 private static void need(boolean value,String message){if(!value)throw new AssertionError("Ramp actor intent: "+message);}
}
